package com.bookstore.config;
import com.bookstore.security.CustomUserDetailsService; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.SecurityFilterChain;
@Configuration @EnableMethodSecurity public class SecurityConfig { @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();} @Bean SecurityFilterChain filterChain(HttpSecurity http,CustomUserDetailsService uds)throws Exception{http.authorizeHttpRequests(a->a.requestMatchers("/","/css/**","/js/**","/login","/register","/h2-console/**","/api/auth/**","/api/books/**").permitAll().requestMatchers("/admin/**").hasRole("ADMIN").anyRequest().authenticated()).formLogin(f->f.loginPage("/login").defaultSuccessUrl("/",true).permitAll()).logout(l->l.logoutSuccessUrl("/").permitAll()).csrf(c->c.ignoringRequestMatchers("/h2-console/**","/api/**")).headers(h->h.frameOptions(fr->fr.sameOrigin())); return http.build();}}
